contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint d) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(address(this).balance >= d, "not enough balance for deposit");

        c.Deposit{value: d}(); if (__ESBMC_reverted()) return;

        uint balAfterDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(balAfterDeposit >= d);
    }
}

